// Warp Core Crystal - mission time demo (Mark 1 demonstration run)
// Run with: node demo.js
'use strict';
var C=299792.458; // km/s, speed of light
function travelTime(distanceLy, warpC){
  var seconds = distanceLy*9.4607e12/(warpC*C);
  var days = seconds/86400;
  if(days<2) return (seconds/3600).toFixed(1)+" hours";
  if(days<730) return days.toFixed(1)+" days";
  return (days/365.25).toFixed(2)+" years";
}
var models=[1.2,9.6,214];
var effs=[41,78,96];
var targets=[["Proxima Centauri",4.24],["Galactic Center",26000],["Andromeda",2537000]];
console.log("Warp Core Crystal - mission times by model generation");
console.log("==================================================");
for(var m=0;m<3;m++){
  console.log("Mark "+(m+1)+": "+models[m]+"c effective, "+effs[m]+"% efficiency");
  for(var i=0;i<targets.length;i++){
    console.log("  -> "+targets[i][0]+" ("+targets[i][1]+" ly): "+travelTime(targets[i][1],models[m]));
  }
}
console.log("Compounding: Mark III is "+(models[2]/models[0]).toFixed(1)+"x faster than Mark I.");

